<template><div class="portal-page"><header><h1>Contratos</h1><p>Consulta y descarga tus contratos</p></header><div class="card"><div class="toolbar"><input v-model="search" placeholder="Buscar por número, asunto o estado..." @input="debounceFetch"></div><div v-if="loading" class="state">Cargando contratos...</div><template v-else><div v-if="!contracts.length" class="state">No hay contratos disponibles</div><div v-else class="table-wrap"><table><thead><tr><th>Número</th><th>Asunto</th><th>Tipo</th><th>Período</th><th>Valor</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="c in contracts" :key="c.id"><td><router-link :to="`/contracts/${c.id}`">{{c.contract_number}}</router-link></td><td>{{c.subject||'—'}}</td><td>{{c.type||'—'}}</td><td>{{c.start_date||'—'}} → {{c.end_date||'—'}}</td><td>{{formatMoney(c.value)}}</td><td>{{statusLabel(c.status)}}</td><td><router-link :to="`/contracts/${c.id}`">Ver</router-link></td></tr></tbody></table></div><div v-if="totalRows>pageSize" class="pagination"><button :disabled="page<=1" @click="page--;fetch()">Anterior</button><span>Página {{page}} de {{totalPages}}</span><button :disabled="page>=totalPages" @click="page++;fetch()">Siguiente</button></div></template></div></div></template><script>export default{data(){return{contracts:[],search:'',page:1,pageSize:10,totalRows:0,loading:false,debounce:null}},computed:{totalPages(){return Math.ceil(this.totalRows/this.pageSize)||1}},mounted(){this.fetch()},methods:{async fetch(){this.loading=true;try{const{data}=await axios.get('/portal/contracts',{params:{page:this.page,limit:this.pageSize,search:this.search||undefined}});this.contracts=data.contracts||[];this.totalRows=data.totalRows||0}catch(_){}this.loading=false},debounceFetch(){clearTimeout(this.debounce);this.debounce=setTimeout(()=>{this.page=1;this.fetch()},300)},formatMoney(n){if(n==null)return'—';return Number(n).toLocaleString('es-HN',{minimumFractionDigits:2,maximumFractionDigits:2})},statusLabel(v){const s=(v||'').toLowerCase();return {active:'Activo',signed:'Firmado',draft:'Borrador',pending:'Pendiente',expired:'Vencido',cancelled:'Cancelado',terminated:'Finalizado'}[s]||v||'—'}}}</script><style scoped>header{margin-bottom:1.25rem}h1{margin:0}header p{margin:.2rem 0 0;color:var(--pc-text-muted)}.card{background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:var(--pc-radius);overflow:hidden}.toolbar{padding:1rem}.toolbar input{width:100%;padding:.65rem;border:1px solid var(--pc-border-strong);border-radius:8px;box-sizing:border-box}.state{padding:3rem;text-align:center;color:var(--pc-text-muted)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:.75rem 1rem;border-bottom:1px solid var(--pc-border);text-align:left}th{background:var(--pc-surface-alt)}a{color:var(--pc-primary)}.pagination{display:flex;justify-content:center;align-items:center;gap:1rem;padding:1rem}.pagination button{padding:.5rem 1rem;border:1px solid var(--pc-border-strong);border-radius:8px;background:var(--pc-surface)}</style>